package pe.clinica.cardenas.encounterservice.config;
import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import pe.clinica.cardenas.encounterservice.domain.*; import pe.clinica.cardenas.encounterservice.repository.*; import java.math.BigDecimal; import java.time.*;
@Configuration @Profile("local") public class LocalDataInitializer {
 @Bean CommandLineRunner encounterData(TreatmentCatalogRepository t,BackupVerificationRepository b){return args->{if(t.count()==0){t.save(TreatmentCatalog.builder().name("Evaluación general").category("GENERALES").specialty("Odontología general").defaultDurationMinutes(30).referencePrice(BigDecimal.valueOf(50)).active(true).build());t.save(TreatmentCatalog.builder().name("Limpieza dental").category("GENERALES").specialty("Odontología general").defaultDurationMinutes(45).referencePrice(BigDecimal.valueOf(120)).active(true).build());t.save(TreatmentCatalog.builder().name("Endodoncia").category("ENDODONCIA").specialty("Endodoncia").defaultDurationMinutes(90).referencePrice(BigDecimal.valueOf(850)).active(true).build());t.save(TreatmentCatalog.builder().name("Extracción dental").category("GENERALES").specialty("Cirugía oral").defaultDurationMinutes(60).referencePrice(BigDecimal.valueOf(250)).active(true).build());t.save(TreatmentCatalog.builder().name("Control de ortodoncia").category("ORTODONCIA").specialty("Ortodoncia").defaultDurationMinutes(30).referencePrice(BigDecimal.valueOf(150)).active(true).build());}for(TreatmentCatalog x:t.findAll()){if(x.getCategory()==null||x.getCategory().isBlank()){String sp=x.getSpecialty()==null?"":x.getSpecialty().toUpperCase();x.setCategory(sp.contains("ENDO")?"ENDODONCIA":sp.contains("ORTO")?"ORTODONCIA":"GENERALES");t.save(x);}}if(b.count()==0)b.save(BackupVerification.builder().backupName("Respaldo local inicial").scope("Bases MySQL y documentos").location("Volúmenes Docker locales").sizeMb(0L).status("PENDIENTE_VERIFICACION").encrypted(false).offsiteCopy(false).completedAt(LocalDateTime.now()).responsible("SYSTEM").notes("Ejecutar RESPALDAR-DEMO.bat y registrar prueba de restauración").build());};}
}
